package vn.xuannhashop;
import java.time.*;
import java.sql.Timestamp;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Supplier;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.test.web.servlet.MockMvc;
import com.fasterxml.jackson.databind.ObjectMapper;
import vn.xuannhashop.business.maintenance.application.*;
import vn.xuannhashop.business.maintenance.application.InspectionChecklistApplication.*;
import vn.xuannhashop.business.reservation.application.ReservationApplication;
import vn.xuannhashop.business.reporting.application.EquipmentHistoryApplication;
import vn.xuannhashop.business.rental.application.RentalApplication;
import vn.xuannhashop.business.shared.DomainException;
import vn.xuannhashop.infrastructure.config.DevSeed;
import static org.assertj.core.api.Assertions.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest(properties={"app.jobs-enabled=false"})
@AutoConfigureMockMvc
class InspectionChecklistTest {
    @Autowired InspectionChecklistApplication checklists;@Autowired MaintenanceApplication maintenance;@Autowired MaintenancePlanningApplication plans;
    @Autowired EquipmentHistoryApplication history;@Autowired ReservationApplication reservations;@Autowired RentalApplication rentals;
    @Autowired JdbcTemplate db;@Autowired MockMvc mvc;@Autowired ObjectMapper json;
    @Autowired vn.xuannhashop.business.shared.Commands commands;
    @Autowired org.springframework.transaction.support.TransactionTemplate transactions;
    String key(){return UUID.randomUUID().toString();}
    <T>T as(String user,Supplier<T> action){var old=SecurityContextHolder.getContext();var current=SecurityContextHolder.createEmptyContext();current.setAuthentication(UsernamePasswordAuthenticationToken.authenticated(user,null,List.of()));SecurityContextHolder.setContext(current);try{return action.get();}finally{SecurityContextHolder.setContext(old);}}
    void act(String user,Runnable action){as(user,()->{action.run();return null;});}
    record Fixture(UUID type,UUID asset) {}
    Fixture fixture(){UUID type=UUID.randomUUID(),asset=UUID.randomUUID();String code="C-"+key().substring(0,8);db.update("insert into equipment_type(id,code,name,category,description,specifications,icon,daily_rate,deposit) values(?,?,'JUNIT Checklist','Test','Test','Test','fan',100,200)",type,code);db.update("insert into equipment(id,code,type_id,warehouse_id,state) select ?,?,?,id,'READY' from warehouse limit 1",asset,code+"-001",type);return new Fixture(type,asset);}
    Publish definition(long version,String label){return new Publish(version,List.of(new Criterion("CABLE",label,true),new Criterion("SURFACE","Ngoại quan",false)),"JUNIT quy trình kiểm tra");}
    UUID publish(Fixture f,Publish input){return as("owner",()->checklists.publish(f.type(),input,key()));}
    Input input(long version,boolean passed){return new Input(true,true,true,"JUNIT kết quả thực tế",version,List.of(new Answer("CABLE",passed,passed?"":"Cần sửa dây"),new Answer("SURFACE",false,"Vết xước nhẹ đã ghi nhận")));}
    UUID inspect(Fixture f,Input input){return as("technician",()->maintenance.inspect(f.asset(),input,key()));}
    String state(Fixture f){return db.queryForObject("select state from equipment where id=?",String.class,f.asset());}
    int count(Fixture f){return db.queryForObject("select count(*) from inspection where equipment_id=?",Integer.class,f.asset());}
    @Test void versionsAreImmutableAndPublishingIsIdempotent(){var f=fixture();assertThat(as("technician",()->checklists.current(f.type())).version()).isZero();String k=key();var c=definition(0,"Dây nguồn an toàn");UUID id=as("owner",()->checklists.publish(f.type(),c,k));assertThat(as("owner",()->checklists.publish(f.type(),c,k))).isEqualTo(id);publish(f,definition(1,"Dây nguồn và phích cắm an toàn"));var rows=as("owner",()->checklists.history(f.type()));assertThat(rows).hasSize(2);assertThat(rows.get(1).get("checks").toString()).contains("Dây nguồn an toàn");assertThat(as("owner",()->checklists.current(f.type())).version()).isEqualTo(2);assertThatThrownBy(()->publish(f,c)).isInstanceOf(DomainException.class);}
    @Test void retryOfPreUpgradeOperationKeepsOriginalResultEvenAfterChecklistChanges(){var f=fixture();String k=key();UUID old=UUID.randomUUID();as("technician",()->transactions.execute(tx->commands.once(k,"INSPECT:"+f.asset()+":true:true:true:Legacy evidence",()->old)));publish(f,definition(0,"New criteria"));assertThat(as("technician",()->maintenance.inspect(f.asset(),true,true,true,"Legacy evidence",k))).isEqualTo(old);assertThat(count(f)).isZero();}
    @Test void requiredFailureBlocksAvailabilityAndSnapshotsStayUnchangedAfterPolicyEdit(){var f=fixture();publish(f,definition(0,"Dây nguồn an toàn"));UUID failed=inspect(f,input(1,false));assertThat(state(f)).isEqualTo("MAINTENANCE");Instant from=Instant.now().plusSeconds(3600);assertThat(reservations.available(f.type(),from,from.plusSeconds(3600))).isZero();assertThat(db.queryForObject("select count(*) from inspection_check_result where inspection_id=?",Integer.class,failed)).isEqualTo(5);publish(f,definition(1,"Nhãn phiên bản mới"));assertThat(db.queryForObject("select label from inspection_check_result where inspection_id=? and code='CABLE'",String.class,failed)).isEqualTo("Dây nguồn an toàn");UUID success=inspect(f,input(2,true));assertThat(state(f)).isEqualTo("READY");assertThat(db.queryForObject("select passed from inspection where id=?",Boolean.class,success)).isTrue();assertThat(db.queryForObject("select count(*) from maintenance_ticket where equipment_id=? and status='OPEN'",Integer.class,f.asset())).isZero();}
    @Test void baseSafetyCannotBeBypassedAndLegacyInspectionsAreNotInvented(){var f=fixture();UUID legacy=UUID.randomUUID();db.update("insert into inspection(id,equipment_id,checklist_version,passed,findings,inspected_by) values(?,?,'DEV-1',true,'Old aggregate only','technician')",legacy,f.asset());publish(f,definition(0,"Dây nguồn"));var good=input(1,true);inspect(f,new Input(false,true,true,good.findings(),1L,good.answers()));assertThat(state(f)).isEqualTo("MAINTENANCE");assertThat(db.queryForObject("select results_recorded from inspection where id=?",Boolean.class,legacy)).isFalse();assertThat(db.queryForObject("select count(*) from inspection_check_result where inspection_id=?",Integer.class,legacy)).isZero();}
    @Test void missingStaleDuplicateUnknownAndUnexplainedAnswersNeverWrite(){var f=fixture();publish(f,definition(0,"Dây nguồn"));var bad=new ArrayList<Input>();bad.add(input(0,true));bad.add(new Input(true,true,true,"JUNIT",null,List.of()));bad.add(new Input(true,true,true,"JUNIT",1L,List.of()));bad.add(new Input(true,true,true,"JUNIT",1L,List.of(new Answer("CABLE",true,""),new Answer("CABLE",true,""))));bad.add(new Input(true,true,true,"JUNIT",1L,List.of(new Answer("OTHER",true,""),new Answer("SURFACE",true,""))));bad.add(new Input(true,true,true,"JUNIT",1L,List.of(new Answer("CABLE",false,""),new Answer("SURFACE",true,""))));bad.add(new Input(true,true,true,"JUNIT",1L,List.of(new Answer("CABLE",null,""),new Answer("SURFACE",true,""))));for(var c:bad)assertThatThrownBy(()->inspect(f,c)).isInstanceOf(DomainException.class);assertThat(count(f)).isZero();assertThat(state(f)).isEqualTo("READY");}
    @Test void apiPermissionsCsrfAndPublishValidationAreEnforced()throws Exception{var f=fixture();String url="/api/maintenance/checklists/"+f.type(),body=json.writeValueAsString(definition(0,"Dây nguồn"));for(String actor:List.of("technician","stock","customer","accountant"))mvc.perform(post(url).with(user(actor)).with(csrf()).header("Idempotency-Key",key()).contentType("application/json").content(body)).andExpect(status().isForbidden());mvc.perform(post(url).with(user("owner")).header("Idempotency-Key",key()).contentType("application/json").content(body)).andExpect(status().isForbidden());mvc.perform(get(url).with(user("customer"))).andExpect(status().isForbidden());mvc.perform(get(url).with(user("technician"))).andExpect(status().isOk());for(var criteria:List.of(List.of(new Criterion("BASE_SAFE","Override",true)),List.of(new Criterion("X","",true)),List.of(new Criterion("X","Valid",null)),List.of(new Criterion("X","One",true),new Criterion("X","Two",true))))assertThatThrownBy(()->publish(f,new Publish(0L,criteria,"JUNIT"))).isInstanceOf(DomainException.class);assertThatThrownBy(()->publish(f,new Publish(0L,Collections.nCopies(21,new Criterion("X","Test",true)),"JUNIT"))).isInstanceOf(DomainException.class);}
    @Test void concurrentPublishHasOneWinner()throws Exception{var f=fixture();var pool=Executors.newFixedThreadPool(2);var gate=new CountDownLatch(1);try{var futures=new ArrayList<Future<Boolean>>();for(String label:List.of("A","B"))futures.add(pool.submit(()->{gate.await();try{publish(f,definition(0,label));return true;}catch(DomainException e){return false;}}));gate.countDown();int wins=0;for(var future:futures)if(future.get(20,TimeUnit.SECONDS))wins++;assertThat(wins).isEqualTo(1);assertThat(as("owner",()->checklists.history(f.type()))).hasSize(1);}finally{pool.shutdownNow();}}
    @Test void publishAndInspectionRaceNeverUseMixedCriteria()throws Exception{var f=fixture();publish(f,definition(0,"Original"));var pool=Executors.newFixedThreadPool(2);var gate=new CountDownLatch(1);try{var publish=pool.submit(()->{gate.await();return publish(f,definition(1,"New"));});var inspect=pool.submit(()->{gate.await();try{return inspect(f,input(1,true));}catch(DomainException e){return null;}});gate.countDown();publish.get(20,TimeUnit.SECONDS);UUID result=inspect.get(20,TimeUnit.SECONDS);if(result!=null){assertThat(db.queryForObject("select label from inspection_check_result where inspection_id=? and code='CABLE'",String.class,result)).isEqualTo("Original");assertThat(db.queryForObject("select type_checklist_version from inspection where id=?",Long.class,result)).isEqualTo(1);}else assertThat(count(f)).isZero();}finally{pool.shutdownNow();}}
    @Test void maintenanceCompletionMustUseCurrentChecklistAndFailedSafetyStaysBlocked(){var f=fixture();publish(f,definition(0,"Dây nguồn"));Instant from=Instant.now().plusSeconds(3600);UUID plan=as("technician",()->plans.schedule(f.asset(),from,from.plusSeconds(3600),"JUNIT maintenance",key()));db.update("update maintenance_plan set starts_at=now()-interval '1 minute' where id=?",plan);db.update("update maintenance_window set occupied_from=now()-interval '1 minute' where id=?",plan);act("technician",()->plans.start(plan,key()));assertThatThrownBy(()->act("technician",()->plans.complete(plan,true,true,true,"Legacy checklist cannot bypass",key()))).isInstanceOf(DomainException.class);assertThat(db.queryForObject("select active from maintenance_window where id=?",Boolean.class,plan)).isTrue();String k=key();act("technician",()->plans.complete(plan,input(1,false),k));act("technician",()->plans.complete(plan,input(1,false),k));assertThat(count(f)).isEqualTo(1);assertThat(state(f)).isEqualTo("MAINTENANCE");assertThat(db.queryForObject("select active from maintenance_window where id=?",Boolean.class,plan)).isFalse();assertThat(reservations.available(f.type(),from,from.plusSeconds(3600))).isZero();}
    @Test void failedSnapshotInsertRollsBackStateInspectionTicketAuditAndCanRetry(){var f=fixture();publish(f,definition(0,"Dây nguồn"));String k=key();db.execute("create function junit_fail_check() returns trigger language plpgsql as $$ begin raise exception 'JUNIT fail'; end $$");db.execute("create trigger junit_fail_check before insert on inspection_check_result for each row execute function junit_fail_check()");try{assertThatThrownBy(()->as("technician",()->maintenance.inspect(f.asset(),input(1,false),k))).isInstanceOf(RuntimeException.class);assertThat(state(f)).isEqualTo("READY");assertThat(count(f)).isZero();assertThat(db.queryForObject("select count(*) from maintenance_ticket where equipment_id=?",Integer.class,f.asset())).isZero();assertThat(db.queryForObject("select count(*) from audit_entry where target_id=? and action='INSPECTION_RECORDED'",Integer.class,f.asset())).isZero();}finally{db.execute("drop trigger junit_fail_check on inspection_check_result");db.execute("drop function junit_fail_check()");}as("technician",()->maintenance.inspect(f.asset(),input(1,false),k));assertThat(count(f)).isEqualTo(1);}
    @SuppressWarnings("unchecked") @Test void equipmentHistoryCombinesEventsPaginatesTiesAndProtectsCustomerData()throws Exception{var f=fixture();publish(f,definition(0,"Dây nguồn"));UUID inspection=inspect(f,input(1,true));Instant from=Instant.now().plusSeconds(86400);UUID order=as("owner",()->rentals.hold(new RentalApplication.Create(DevSeed.id("khach-an"),List.of(new RentalApplication.Line(f.type(),1)),from,from.plusSeconds(86400),"PRIVATE CUSTOMER ADDRESS",true),key()));db.update("update rental_item set handed_at=now()-interval '2 minutes',returned_at=now()-interval '1 minute',return_condition='GOOD' where order_id=?",order);var combined=as("technician",()->history.history(f.asset(),null,null));String serialized=json.writeValueAsString(combined);assertThat(serialized).contains("HANDED_OVER","RETURNED","RENTAL_BOOKED","INSPECTION","Dây nguồn").doesNotContain("PRIVATE CUSTOMER ADDRESS","customerName","phone","rental_total","deposit_required");
        for(int i=0;i<55;i++)db.update("insert into inspection(id,equipment_id,checklist_version,passed,findings,inspected_by,created_at) values(?,?,'DEV-1',true,'JUNIT pagination','technician',?)",UUID.randomUUID(),f.asset(),Timestamp.from(from));
        var first=as("stock",()->history.history(f.asset(),null,null));var events=(List<Map<String,Object>>)first.get("events");assertThat(events).hasSize(50);var cursor=(Map<String,Object>)first.get("nextCursor");var second=as("stock",()->history.history(f.asset(),(Instant)cursor.get("before"),(String)cursor.get("beforeKey")));var rest=(List<Map<String,Object>>)second.get("events");var ids=new HashSet<Object>();events.forEach(e->ids.add(e.get("event_key")));rest.forEach(e->assertThat(ids.add(e.get("event_key"))).isTrue());assertThat(ids).hasSize(59);assertThat(second.get("nextCursor")).isNull();
        mvc.perform(get("/api/equipment/"+f.asset()+"/history").with(user("customer"))).andExpect(status().isForbidden());mvc.perform(get("/api/equipment/"+UUID.randomUUID()+"/history").with(user("technician"))).andExpect(status().isNotFound());assertThatThrownBy(()->as("owner",()->history.history(f.asset(),Instant.now(),null))).isInstanceOf(DomainException.class);
        // The old asset remains linked through released reservations after a pre-handover replacement.
        db.update("delete from inspection where equipment_id=? and findings='JUNIT pagination'",f.asset());
        var replacement=fixture();
        db.update("update rental_item set equipment_id=?,handed_at=null,returned_at=null,return_condition=null where order_id=?",replacement.asset(),order);
        db.update("update reservation set status='RELEASED' where order_id=?",order);
        var oldEvents=(List<Map<String,Object>>)as("owner",()->history.history(f.asset(),null,null)).get("events");
        assertThat(oldEvents.stream().filter(e->"RENTAL_BOOKED".equals(e.get("kind"))).count()).isEqualTo(1);
        assertThat(oldEvents.stream().noneMatch(e->Set.of("HANDED_OVER","RETURNED").contains(e.get("kind")))).isTrue();
    }
}
